import pandas as pd
import re
import difflib

DESIGNATOR_ALIASES = {
    'designator', 'designators', 'refdes', 'refdes(s)', 'reference designator', 'ref des',
    'component designators', 'refs',
}
ARENA_PN_ALIASES = {
    'arena part number', 'arena pn', 'arena number', 'arena p/n', 'arena part #', 'arena part no',
    'item number',
}
MFG_PN_ALIASES = {
    'mfg pn', 'manufacturer pn', 'mfr pn', 'mfg p/n', 'manufacturer p/n', 'mfr p/n',
    'manufacturer part number', 'mfg part number', 'mfr part number', 'mpn',
    'manufacturer item number', 'comment',
}
VENDOR_PN_ALIASES = {
    'vendor pn', 'supplier pn', 'supplier p/n', 'vendor p/n', 'disty pn', 'distributor pn',
    'supplier part number', 'vendor part number', 'supplier part #', 'vendor part #',
    'vendor item number',
}
DESC_ALIASES = {
    'description', 'item description', 'part description', 'desc', 'bom description',
}

MFG_PN_PREFIXES = ('manufacturer part number', 'manufacturer item number')
VENDOR_PN_PREFIXES = ('vendor item number', 'supplier part number')
DESC_PREFIXES = ('vendor item name', 'manufacturer item name')

def _norm_colname(s: str) -> str:
    return re.sub(r'\s+', ' ', str(s or '')).strip().lower()

def _split_designators(cell):
    if pd.isna(cell):
        return []
    text = str(cell)
    parts = re.split(r'[",\s;/\n\r\t]+', text)
    out = []
    for p in parts:
        if not p:
            continue
        m = re.fullmatch(r'([A-Za-z]+)(\d+)-\1(\d+)', p)
        if m:
            prefix = m.group(1)
            a = int(m.group(2))
            b = int(m.group(3))
            lo, hi = (a, b) if a <= b else (b, a)
            out.extend([f'{prefix}{i}' for i in range(lo, hi + 1)])
        else:
            out.append(p)
    return [d.strip() for d in out if d.strip()]

def _norm_text(x):
    if x is None or (isinstance(x, float) and pd.isna(x)):
        return ''
    s = str(x).strip().lower()
    s = re.sub(r'[^a-z0-9.+\- ]+', ' ', s)
    s = re.sub(r'\s+', ' ', s).strip()
    return s

def _similar(a, b):
    if not a or not b:
        return 0.0
    return difflib.SequenceMatcher(None, a, b).ratio()

def _find_col(df, alias_set):
    cols = { _norm_colname(c): c for c in df.columns }
    for norm, orig in cols.items():
        if norm in alias_set:
            return orig
    for norm, orig in cols.items():
        if any(a in norm for a in alias_set):
            return orig
    return None

def _find_cols_with_alias_or_prefix(df, alias_set, prefixes):
    cols = []
    for c in df.columns:
        norm = _norm_colname(c)
        if norm in alias_set or any(norm.startswith(p) for p in prefixes):
            cols.append(c)
    if not cols:
        for c in df.columns:
            norm = _norm_colname(c)
            if any(a in norm for a in alias_set):
                cols.append(c)
    return cols

def _collect_first_nonempty(row, cols):
    for c in cols:
        val = row.get(c)
        if val not in (None, '') and pd.notna(val):
            return val
    return None

def _collect_all_nonempty(row, cols):
    out = []
    for c in cols:
        val = row.get(c)
        if val not in (None, '') and pd.notna(val):
            out.append(val)
    return out

def load_bom(path: str):
    encodings_to_try = ['utf-8', 'utf-16', 'cp1252', 'latin1']
    last_err = None
    df = None
    for enc in encodings_to_try:
        try:
            df = pd.read_csv(path, dtype=str, keep_default_na=False, encoding=enc)
            last_err = None
            break
        except Exception as e:
            last_err = e
    if df is None:
        raise last_err

    df = df.replace({'': None})

    designator_col = _find_col(df, DESIGNATOR_ALIASES) or 'Designator'
    arena_pn_col  = _find_col(df, ARENA_PN_ALIASES)

    mfg_cols = _find_cols_with_alias_or_prefix(df, MFG_PN_ALIASES, tuple(p.lower() for p in MFG_PN_PREFIXES))
    vendor_cols = _find_cols_with_alias_or_prefix(df, VENDOR_PN_ALIASES, tuple(p.lower() for p in VENDOR_PN_PREFIXES))
    desc_cols = _find_cols_with_alias_or_prefix(df, DESC_ALIASES, tuple(p.lower() for p in DESC_PREFIXES))
    if _find_col(df, {'description'}):
        dcol = _find_col(df, {'description'})
        if dcol not in desc_cols:
            desc_cols.append(dcol)

    per_ref = {}
    duplicates = set()

    for _, row in df.iterrows():
        refs = _split_designators(row.get(designator_col))
        if not refs:
            continue

        arena_raw = row.get(arena_pn_col) if arena_pn_col else None
        mfg_raw_list = _collect_all_nonempty(row, mfg_cols)
        vendor_raw_list = _collect_all_nonempty(row, vendor_cols)
        desc_raw = _collect_first_nonempty(row, desc_cols)

        entry = {
            'arena_pn_set': { _norm_text(v) for v in ([arena_raw] if arena_raw else []) if _norm_text(v) },
            'mfg_pn_set': { _norm_text(v) for v in mfg_raw_list if _norm_text(v) },
            'vendor_pn_set': { _norm_text(v) for v in vendor_raw_list if _norm_text(v) },
            'description': _norm_text(desc_raw),
            'raw': {
                'arena_pn': arena_raw,
                'mfg_pn_list': mfg_raw_list,
                'vendor_pn_list': vendor_raw_list,
                'description': desc_raw,
            }
        }
        for r in refs:
            if r in per_ref:
                duplicates.add(r)
            per_ref.setdefault(r, entry)
    return per_ref, {'duplicates': sorted(duplicates)}

def _sets_intersect(a, b):
    return bool(a and b and (a & b))

def compare_boms(altium_path: str, arena_path: str):
    alt_map, alt_meta = load_bom(altium_path)
    arn_map, arn_meta = load_bom(arena_path)

    all_refs = sorted(set(alt_map.keys()) | set(arn_map.keys()))
    rows = []
    for ref in all_refs:
        alt = alt_map.get(ref)
        arn = arn_map.get(ref)
        if alt is None and arn is not None:
            rows.append({
                'designator': ref, 'status': 'missing_in_altium', 'key_used': '',
                'altium_arenaPN': '', 'arena_arenaPN': arn['raw']['arena_pn'],
                'altium_mfgPNs': '', 'arena_mfgPNs': '; '.join(arn['raw']['mfg_pn_list']) if arn['raw']['mfg_pn_list'] else '',
                'altium_vendorPNs': '', 'arena_vendorPNs': '; '.join(arn['raw']['vendor_pn_list']) if arn['raw']['vendor_pn_list'] else '',
                'altium_desc': '', 'arena_desc': arn['raw']['description'], 'similarity': ''
            })
            continue
        if arn is None and alt is not None:
            rows.append({
                'designator': ref, 'status': 'missing_in_arena', 'key_used': '',
                'altium_arenaPN': next(iter(alt['arena_pn_set']), ''),
                'arena_arenaPN': '',
                'altium_mfgPNs': '; '.join(alt['raw']['mfg_pn_list']) if alt['raw']['mfg_pn_list'] else '',
                'arena_mfgPNs': '',
                'altium_vendorPNs': '; '.join(alt['raw']['vendor_pn_list']) if alt['raw']['vendor_pn_list'] else '',
                'arena_vendorPNs': '',
                'altium_desc': alt['raw']['description'], 'arena_desc': '', 'similarity': ''
            })
            continue

        status = 'mismatch'
        key_used = None
        similarity = ''

        if alt['description'] == arn['description']:
            status = 'match'
            key_used = 'description'
        elif _sets_intersect(alt['arena_pn_set'], arn['arena_pn_set']):
            status = 'match'
            key_used = 'arena_pn'
        elif _sets_intersect(alt['mfg_pn_set'], arn['mfg_pn_set']):
            status = 'match'
            key_used = 'mfg_pn'
        elif _sets_intersect(alt['vendor_pn_set'], arn['vendor_pn_set']):
            status = 'match'
            key_used = 'vendor_pn'

        rows.append({
            'designator': ref, 'status': status, 'key_used': key_used,
            'altium_arenaPN': next(iter(alt['arena_pn_set']), ''),
            'arena_arenaPN': next(iter(arn['arena_pn_set']), ''),
            'altium_mfgPNs': '; '.join(alt['raw']['mfg_pn_list']) if alt['raw']['mfg_pn_list'] else '',
            'arena_mfgPNs': '; '.join(arn['raw']['mfg_pn_list']) if arn['raw']['mfg_pn_list'] else '',
            'altium_vendorPNs': '; '.join(alt['raw']['vendor_pn_list']) if alt['raw']['vendor_pn_list'] else '',
            'arena_vendorPNs': '; '.join(arn['raw']['vendor_pn_list']) if arn['raw']['vendor_pn_list'] else '',
            'altium_desc': alt['raw']['description'], 'arena_desc': arn['raw']['description'],
            'similarity': similarity
        })

    df = pd.DataFrame(rows)
    order = pd.CategoricalDtype(categories=['missing_in_altium','missing_in_arena','mismatch','match'], ordered=True)
    df['status'] = df['status'].astype(order)
    df = df.sort_values(['status','designator']).reset_index(drop=True)

    meta = {'altium_duplicates': alt_meta.get('duplicates', []),
            'arena_duplicates': arn_meta.get('duplicates', [])}
    return df, meta

def save_report(df: pd.DataFrame, meta: dict, out_csv: str, out_json: str):
    df.to_csv(out_csv, index=False)
    with open(out_json, 'w', encoding='utf-8') as f:
        import json as _json
        _json.dump(meta, f, indent=2)

if __name__ == "__main__":
    import argparse
    p = argparse.ArgumentParser(description="Compare two BOM CSVs by designator with flexible part-number matching.")
    p.add_argument("--altium", required=True, help="Path to Altium CSV")
    p.add_argument("--arena", required=True, help="Path to Arena CSV")
    p.add_argument("--out-csv", default="bom_compare_report.csv", help="Output CSV path")
    p.add_argument("--out-meta", default="bom_compare_meta.json", help="Output JSON path for metadata like duplicates")
    args = p.parse_args()

    df, meta = compare_boms(args.altium, args.arena)
    save_report(df, meta, args.out_csv, args.out_meta)
    print(f"Saved: {args.out_csv}")
    print(f"Saved: {args.out_meta}")
